#include "navcore/spatial_index.hpp"
#include <algorithm>
#include <fstream>
#include <limits>
#include <vector>
namespace { const navcore::Edge* best(const navcore::RoadGraph&g,const std::vector<navcore::Edge>&es,double lat,double lon){const navcore::Edge* r=nullptr;double b=std::numeric_limits<double>::infinity();for(const auto&e:es){auto&a=g.node(e.from);auto&z=g.node(e.to);double d=std::min(navcore::haversine_m(a,{"",lat,lon}),navcore::haversine_m(z,{"",lat,lon}));if(d<b){b=d;r=&e;}}return r;} double p95(std::vector<double>v){std::sort(v.begin(),v.end());return v[v.size()*95/100];}}
int main(){auto g=navcore::make_grid_network(100,100);navcore::SpatialIndex idx(g);std::vector<navcore::Edge> all;for(const auto&n:g.nodes())for(const auto&e:g.outgoing(n.first))all.push_back(e);std::vector<double> il,bl;double ic=0,bc=0;int agree=0;std::vector<std::string> samples;for(int n=0;n<1000;++n){double lat=30+(n%100)*.001,lon=120+(n/100)*.001;auto t=std::chrono::steady_clock::now();auto b=best(g,all,lat,lon);bl.push_back(std::chrono::duration<double,std::micro>(std::chrono::steady_clock::now()-t).count());t=std::chrono::steady_clock::now();navcore::SpatialQueryStats st;auto v=idx.query(lat,lon,200,&st);auto q=best(g,v,lat,lon);il.push_back(std::chrono::duration<double,std::micro>(std::chrono::steady_clock::now()-t).count());bc+=all.size();ic+=v.size();if(b&&q&&navcore::edge_key(*b)==navcore::edge_key(*q))++agree;else if(samples.size()<5)samples.push_back(std::to_string(n));}double ia=0,ba=0;for(auto x:il)ia+=x;for(auto x:bl)ba+=x;ia/=il.size();ba/=bl.size();double rate=static_cast<double>(agree)/1000;std::ofstream c("reports/v3_spatial_benchmark.csv");c<<"total_samples,indexed_matches,brute_force_matches,agreement_count,agreement_rate,indexed_average_latency_us,brute_force_average_latency_us,indexed_p95_latency_us,brute_force_p95_latency_us,indexed_average_candidates,brute_force_average_candidates,candidate_reduction_ratio,mismatch_count\n1000,"<<agree<<",1000,"<<agree<<','<<rate<<','<<ia<<','<<ba<<','<<p95(il)<<','<<p95(bl)<<','<<ic/1000<<','<<bc/1000<<','<<1-ic/bc<<','<<1000-agree<<'\n';std::ofstream m("reports/v3_spatial_benchmark.md");m<<"# V3 spatial benchmark\n\nReal per-sample brute-force/indexed final-edge comparison. Agreement: "<<agree<<"/1000 ("<<rate<<").\n\nMismatches: ";for(const auto&s:samples)m<<s<<' ';m<<"\n";}